package imazingcsv

import (
	"bytes"
	"compress/gzip"
	_ "embed"
	"io"
	"os"
	"path/filepath"
	"testing"
	"time"

	Assert "github.com/stretchr/testify/assert"   //nolint:importas // Keep the package constructor available beside local helpers.
	Require "github.com/stretchr/testify/require" //nolint:importas // Keep the package constructor available beside local helpers.
	"go.kenn.io/msgvault/internal/store"
	"go.kenn.io/msgvault/internal/testutil"
)

// Synthetic archive generated by the unmodified native importer and schema at
// 8799dfacec52b3a71849b6776ba864863cd69537. Both rows share a duplicate base;
// the second has read evidence. No new allocation records were removed to
// construct this fixture: the original schema has no allocation table.
//
//go:embed testdata/import-original-native-8799.sqlite.gz
var originalNativeImazingArchive []byte

func TestImportImazingOriginalNativeArchiveUpgradeRetainsOccurrences(t *testing.T) {
	assert := Assert.New(t)

	require := Require.New(t)

	testutil.SkipIfPostgres(t, "this fixture exercises a real native SQLite archive upgrade")
	reader, err := gzip.NewReader(bytes.NewReader(originalNativeImazingArchive))
	require.NoError(err)
	contents, err := io.ReadAll(reader)
	require.NoError(err)
	require.NoError(reader.Close())
	dbPath := filepath.Join(t.TempDir(), "archive.sqlite")
	require.NoError(os.WriteFile(dbPath, contents, 0o600))
	st, err := store.OpenForTest(dbPath)
	require.NoError(err)
	t.Cleanup(func() { Require.NoError(t, st.Close()) })
	require.NoError(st.InitSchema())
	source, err := st.GetSourceByTypeAndIdentifier(SourceType, "+15550000001")
	require.NoError(err)
	before := archivedDuplicateEvidence(t, st, source.ID)
	require.Len(before, 2)
	removed := findArchivedEvidence(t, before, "", "")
	retained := findArchivedEvidence(t, before, "Read", "")
	_, err = st.ConfigureMCPEvents(t.Context(), store.MCPEventsConfig{Enabled: true, ImportNotifications: true, Principal: "owner:synthetic-upgrade", Capabilities: []store.MCPEventCapability{{Family: "msgvault.import_message_archived", SourceType: "eml", Kinds: []string{"message"}}}})
	require.NoError(err)
	var allocations, runs, events int
	require.NoError(st.DB().QueryRow("SELECT COUNT(*) FROM import_occurrence_allocations").Scan(&allocations))
	assert.Equal(2, allocations)
	require.NoError(st.DB().QueryRow("SELECT COUNT(*) FROM import_runs").Scan(&runs))
	assert.Zero(runs, "cutover must not invent historical logical imports")
	require.NoError(st.DB().QueryRow("SELECT COUNT(*) FROM mcp_event_log").Scan(&events))
	assert.Zero(events)
	_, err = st.DB().ExecContext(t.Context(), st.Rebind("UPDATE messages SET deleted_at=?,delete_batch_id=? WHERE id=?"), time.Now().UTC(), "synthetic-native-upgrade-delete", removed.messageID)
	require.NoError(err)
	deleted, err := st.DeleteDedupedBatchContext(t.Context(), "synthetic-native-upgrade-delete")
	require.NoError(err)
	require.Equal(int64(1), deleted)
	read := []string{"Synthetic Contact", "2024-06-01 12:00:00", "", "2024-06-01 12:00:10", "iMessage", "Incoming", "sender@example.net", "Synthetic Sender", "Read", "", "", "Synthetic old native import", "", ""}
	export := newTestExport(t, [][]string{read})
	importer := NewImporter(st, Options{Owner: "+15550000001", Timezone: "UTC"})
	_, err = importer.ImportPath(t.Context(), export)
	require.NoError(err)
	after := archivedDuplicateEvidence(t, st, source.ID)
	require.Len(after, 1)
	assert.Equal(retained.messageID, after[0].messageID)
	assert.Equal(retained.sourceMessageID, after[0].sourceMessageID)
	plain := append([]string(nil), read...)
	plain[3] = ""
	plain[8] = ""
	writeTestCSV(t, filepath.Join(export, "csv", "messages.csv"), [][]string{read, plain})
	_, err = importer.ImportPath(t.Context(), export)
	require.NoError(err)
	restored := archivedDuplicateEvidence(t, st, source.ID)
	require.Len(restored, 2)
	assert.Equal(removed.sourceMessageID, findArchivedEvidence(t, restored, "", "").sourceMessageID)
	require.NoError(st.DB().QueryRow("SELECT COUNT(*) FROM import_occurrence_allocations").Scan(&allocations))
	assert.Equal(2, allocations)
	require.NoError(st.DB().QueryRow("SELECT COUNT(*) FROM mcp_event_log").Scan(&events))
	assert.Zero(events)
}
